import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, ReplaySubject, of, switchMap, tap } from 'rxjs';
import { Currency } from './invoice-format';
export interface ClientBalance {
  clientId: number;
  balance: string;
  overdue: string;
  credit: string;
}

// The invoices REST API.
@Injectable({ providedIn: 'root' })
export class InvoiceService {
  private readonly http = inject(HttpClient);
  // Completes once the latest payment spread over a client's invoices has been answered, so an
  // invoice opened meanwhile is read with it.
  private paymentSettled: Observable<unknown> = of(null);

  forClient(clientId: number): Observable<InvoiceSummary[]> {
    return this.paymentSettled.pipe(
      switchMap(() => this.http.get<InvoiceSummary[]>(`/api/clients/${clientId}/invoices`)),
    );
  }

import { HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, input, output, signal, untracked } from '@angular/core';
import { InvoiceDetail, InvoiceService, InvoiceSummary } from './invoice.service';
import { PaymentForm } from './payment-form';
import { RefundForm } from './refund-form';
import { RateForm } from './rate-form';
import { InvoicePanel } from './invoice-panel';
import { Currency, money, statusLabel } from './invoice-format';

// One client's invoices, each with its status, total, issue and due dates. Clicking an invoice
// opens it in the invoice panel beside the list; New invoice starts an empty draft and opens it.
// An invoice looked up by its number is opened as soon as its client's invoices are shown.

